INSERT INTO `SERVMASK_PREFIX_posts` VALUES (9,1,'2025-01-09 21:14:16','2025-01-09 21:14:16','<p>ST STORE</p>\n<h2>Especializados en la Venta de Equipos y Maquinaria Industrial</h2>\n<p>Somos ST STORE es una empresa especializada en la venta de equipos industriales y de construcción, con stock disponible para entrega inmediata.</p>\n<p>					<a href=\"https://wa.link/7cg6f1\" target=\"_blank\"><br />\n									¡ Cotizar Productos !<br />\n					</a><br />\n															<img width=\"500\" height=\"500\" src=\"https://strental.com.pe/wp-content/uploads/2025/03/file-5vSehHPxkyfKhmDNFyJ59W-removebg-preview.png\" alt=\"\" srcset=\"https://strental.com.pe/wp-content/uploads/2025/03/file-5vSehHPxkyfKhmDNFyJ59W-removebg-preview.png 500w, https://strental.com.pe/wp-content/uploads/2025/03/file-5vSehHPxkyfKhmDNFyJ59W-removebg-preview-300x300.png 300w, https://strental.com.pe/wp-content/uploads/2025/03/file-5vSehHPxkyfKhmDNFyJ59W-removebg-preview-150x150.png 150w, https://strental.com.pe/wp-content/uploads/2025/03/file-5vSehHPxkyfKhmDNFyJ59W-removebg-preview-100x100.png 100w\" sizes=\"(max-width: 500px) 100vw, 500px\" />															</p>\n<h2>PROFESIONALES EN INGENERÍA ELÉCTRICA Y METROLOGÍA EN PERÚ</h2>\n<p>					<a href=\"https://strental.com.pe/nosotros/\"><br />\n									SOBRE NOSOTROS<br />\n					</a></p>\n<h2>PRODUCTOS TOP</h2>\n<h2>NUESTRA LÍNEA DE EQUIPOS EN VENTA </h2>\n<h2>MÁS QUE UN PROVEEDOR UN SOCIO COMPROMETIDO</h2>\n<p>					<a href=\"https://wa.link/lcq6u6\"><br />\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M497.39 361.8l-112-48a24 24 0 0 0-28 6.9l-49.6 60.6A370.66 370.66 0 0 1 130.6 204.11l60.6-49.6a23.94 23.94 0 0 0 6.9-28l-48-112A24.16 24.16 0 0 0 122.6.61l-104 24A24 24 0 0 0 0 48c0 256.5 207.9 464 464 464a24 24 0 0 0 23.4-18.6l24-104a24.29 24.29 0 0 0-14.01-27.6z\"></path></svg><br />\n									 +51 941 683 726<br />\n					</a></p>\n<h3>\n							VENTA DE EQUIPOS DE MEDICIÓN						</h3>\n<p>							Contamos con equipos de medición precisos y en stock, listos para la venta e ideales para todo tipo de proyectos industriales.<br />\n											<a href=\"https://strental.com.pe/venta-de-equipos-de-medicion/\"><br />\n							Ver servicios						</a></p>\n<h3>\n							VENTA DE EQUIPOS DE SEGURIDAD						</h3>\n<p>							En ST STORE, ofrecemos equipos de seguridad industrial en stock, listos para la venta, asegurando la protección adecuada para tus proyectos en construcción, minería y más.<br />\n											<a href=\"https://strental.com.pe/venta-de-equipos-de-seguridad/\"><br />\n							Ver servicios						</a></p>\n<h3>\n							VENTA DE MAQUINARIA PESADA						</h3>\n<p>							Compra maquinaria pesada en perfecto estado para tus proyectos de construcción y minería. En ST STORE, te ofrecemos equipos confiables y eficaces.<br />\n											<a href=\"https://strental.com.pe/venta-de-maquinaria-pesada/\"><br />\n							Ver servicios						</a></p>\n<h3>\n							VENTA DE HERRAMIENTAS DE USO INDUSTRIAL						</h3>\n<p>							Disponemos de herramientas industriales de alta calidad para diversos sectores. Nuestro stock disponible cubre todas tus necesidades.<br />\n											<a href=\"https://strental.com.pe/venta-de-herramientas-de-uso-industrial/\"><br />\n							Ver servicios						</a></p>\n<h2>Nuestros Productos en Stock</h2>\n<h2>Nuestra experiencia refleja en cifras de valor</h2>\n<p>			<svg aria-hidden=\"true\" viewBox=\"0 0 496 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M248 8C111 8 0 119 0 256s111 248 248 248 248-111 248-248S385 8 248 8zm0 448c-110.3 0-200-89.7-200-200S137.7 56 248 56s200 89.7 200 200-89.7 200-200 200zm105.6-151.4c-25.9 8.3-64.4 13.1-105.6 13.1s-79.6-4.8-105.6-13.1c-9.8-3.1-19.4 5.3-17.7 15.3 7.9 47.2 71.3 80 123.3 80s115.3-32.9 123.3-80c1.6-9.8-7.7-18.4-17.7-15.3zm-227.9-57.5c-1 6.2 5.4 11 11 7.9l31.3-16.3 31.3 16.3c5.6 3.1 12-1.7 11-7.9l-6-34.9 25.4-24.6c4.5-4.5 1.9-12.2-4.3-13.2l-34.9-5-15.5-31.6c-2.9-5.8-11-5.8-13.9 0l-15.5 31.6-34.9 5c-6.2